// Sound effects for Islam's 2-3 years Dagestan special (Joe's clips, 2026-11-22).
// Sound effects, not voice lines, so they play straight to the speakers and
// stay off the talk channel (CLAUDE.md). Source cuts: project-files/sound/islam/.
//   islamVanScreech  the van skidding in (myinstants)            van in, van off, the van in Dagestan
//   islamBeating     the brawl in the dust cloud (myinstants)    the beating, faded out as the cloud clears
//   islamCatapult    designed medieval catapult launch (Soundsnap preview, licence unchecked)   the release and the slam
//   islamThump       body drop thump (Soundsnap preview, licence unchecked)   bodies hitting the ground or the spoon
"use strict";
if (typeof SOUND_CLIPS !== "undefined") {
  SOUND_CLIPS.islamVanScreech = "data:audio/mpeg;base64,";
  SOUND_CLIPS.islamBeating = "data:audio/mpeg;base64,";
  SOUND_CLIPS.islamCatapult = "data:audio/mpeg;base64,";
  SOUND_CLIPS.islamThump = "data:audio/mpeg;base64,";
}
var ISLAM_SFX = ["islamVanScreech", "islamBeating", "islamCatapult", "islamThump"];
var islamSfxLive = {}; // what's playing, so it can be faded out
// From islamVoiceWarm (islam-voice.js): decode them ahead of time.
function islamSfxWarm() {
  if (typeof withClip !== "function") return;
  ISLAM_SFX.forEach(function (n) { withClip(n); });
}
// Plays one, `delay` seconds from now (0 = now), from `offset` seconds into
// the clip. Silent if not decoded yet.
function islamSfx(name, gain, delay, offset) {
  var ac = typeof audioCtx !== "undefined" ? audioCtx : null, buf = ac && clipBuffers[name];
  if (!buf) { if (typeof withClip === "function") withClip(name); return; }
  try {
    var src = ac.createBufferSource(), g = ac.createGain();
    src.buffer = buf; g.gain.value = gain == null ? 1 : gain;
    src.connect(g); g.connect(ac.destination);
    src.start(ac.currentTime + Math.max(0, delay || 0), offset || 0);
    islamSfxLive[name] = { src: src, g: g };
  } catch (e) {}
}
// Fades one out over `fade` seconds and stops it.
function islamSfxStop(name, fade) {
  var p = islamSfxLive[name], ac = typeof audioCtx !== "undefined" ? audioCtx : null;
  if (!p || !ac) return;
  islamSfxLive[name] = null;
  try {
    var t = ac.currentTime, f = fade || 0.2;
    p.g.gain.cancelScheduledValues(t); p.g.gain.setValueAtTime(p.g.gain.value, t); p.g.gain.linearRampToValueAtTime(0, t + f);
    p.src.stop(t + f + 0.02);
  } catch (e) {}
}
